insert into games (id, data) values ('game-echo-matrix', $j${"id":"game-echo-matrix","title":"Echo Matrix","slug":"echo-matrix","kind":"embed","summary":"An arcade memory game: watch the lights, hear the notes, and tap the pattern back, K to 5th grade.","players":"1","minutes":5,"ageMin":5,"ageMax":11,"rules":["Pick your grade, from Kindergarten to 5th. Older grades get more pads, longer patterns and quicker lights.","Pick Echo to tap the pattern back in the same order, Backwards to start with the last light, or Rush for quicker lights and more points.","Watch the pads light up and listen to their notes. Every pad has its own color, shape and note.","When it says Your turn, tap the same pads in the same order. On a keyboard, use the number keys, or the arrow keys and Enter.","Each round the pattern gets one light longer. Perfect rounds build a streak, up to x5 points.","A wrong tap costs one of your 3 hearts, shows you the right pad, and plays the pattern again.","Need another look? Press Replay. You get 3 in each game.","Every 5 rounds you level up and the lights get a little faster. Your best score is kept on this device.","Sound is on: press the speaker button to turn it off."],"leadsTo":"act-story-cubes","interactive":true,"path":"games/echo-matrix.html","icon":"grid-3x3","p1":"#C8EEF8","p2":"#1C2163","status":"published","featured":true,"createdAt":"2026-11-08T02:15:00.000Z","updatedAt":"2026-11-08T02:15:00.000Z","badge":"New","order":0,"cover":{"src":"assets/games/echo-matrix.jpg","alt":"An Echo Matrix board of nine colored pads, each with its own shape, the purple diamond lit up, three of seven pattern dots filled in, a streak of x5 and Chike saying Your turn!"},"vocabWord":"sequence","vocabSay":"SEE-kwens · noun","vocabMeaning":"A set of things that come one after another, in an order.","vocabExample":"In Echo Matrix, watch the sequence of lights, then tap it back in the same order!"}$j$::jsonb)
